// The MilkDrop host (engine/core/milkdrop.ts): Butterchurn, held to the engine's rules.
//
// It lives outside src/engine because it is a browser library with its own WebGL2 context, and
// because it does what the engine must not: `Math.random` is replaced for the length of each call
// into it, with a generator seeded from the layer. All of Butterchurn's randomness goes through that
// one function, so a preset's "random" noise textures and mesh jitter come out the same every time.
//
// Presets arrive as scripts generated by setup (setup/steps/milkdrop.ts), one per preset, each
// assigning to `globalThis.__pfMilkdrop`. Butterchurn would otherwise compile their maths with
// `new Function`, which the studio's content security policy rightly forbids; given real functions
// it skips that. Only those generated files are ever loaded, never a preset from a project file.

import type imported from 'butterchurn';

import { WAVEFORM_RATE, type MilkdropHost, type MilkdropRequest } from '../engine/core/milkdrop.ts';

let butterchurn: typeof imported | undefined;

/**
 * Butterchurn, the first time a preset needs it. Its bundle reads `window` as it loads, so a plain
 * import would stop anything that reaches this file from loading outside a page.
 */
export async function loadButterchurn(): Promise<void> {
  const loaded = (await import('butterchurn')).default;
  // A webpack bundle that exports its class as `default` of its CommonJS exports.
  butterchurn = (loaded as unknown as { readonly default?: typeof imported }).default ?? loaded;
}

/** On a jump in the preview, how many frames it runs to settle. A quarter of a second at 60 fps. */
const SETTLE_FRAMES = 15;
/** Forward by this many frames or fewer, the preview steps instead of jumping. */
const CATCH_UP_FRAMES = 12;

type PresetTable = Record<string, unknown>;
const scope = globalThis as unknown as { __pfMilkdrop?: PresetTable };

interface Running {
  readonly canvas: HTMLCanvasElement;
  readonly visualizer: ReturnType<typeof imported.createVisualizer>;
  readonly key: string;
  /** The generator's state, carried from call to call. */
  random: number;
  /** The last frame drawn; -1 before the first. */
  frame: number;
  /** What this preset could not run, for the layer to say. */
  problem: string | null;
}

type Preset = Record<string, unknown>;

/** Runs `load`, and gives the first error of every shader that would not link. Butterchurn never asks. */
function failedLinks(gl: WebGL2RenderingContext, load: () => void): string[] {
  const failed: string[] = [];
  const link = gl.linkProgram.bind(gl);
  gl.linkProgram = (program) => {
    link(program);
    if (gl.getProgramParameter(program, gl.LINK_STATUS) === true) return;
    const logs = (gl.getAttachedShaders(program) ?? []).map((shader) => gl.getShaderInfoLog(shader) ?? '');
    failed.push(/ERROR: \d+:\d+: ([^|]*?)(?= ERROR:|$)/.exec(logs.join(' '))?.[1]?.trim() ?? 'it would not link');
  };
  try {
    load();
  } finally {
    delete (gl as Partial<WebGL2RenderingContext>).linkProgram;
  }
  return failed;
}

/**
 * Loads a preset. 23 of the library's presets name a texture file nobody shipped, or code MilkDrop's
 * own compiler let through. Such a program does not link, and Butterchurn then skips that stage on
 * every frame with a WebGL warning, so the picture is wrong and nothing says why. The stage that
 * fails goes back to Butterchurn's default instead, and the layer reports it. A preset whose
 * shaders link takes the first line and nothing else, so its pixels cannot change.
 */
function loadChecked(visualizer: Running['visualizer'], canvas: HTMLCanvasElement, name: string): string | null {
  const preset = scope.__pfMilkdrop?.[name] as Preset | undefined;
  const gl = canvas.getContext('webgl2');
  if (gl === null) throw new Error('The MilkDrop canvas lost its WebGL2 context');
  const failed = failedLinks(gl, () => visualizer.loadPreset(preset, 0));
  if (failed.length === 0) return null;
  for (const stages of [['warp'], ['comp'], ['warp', 'comp']]) {
    const lighter = { ...preset, ...Object.fromEntries(stages.map((stage) => [stage, ''])) };
    if (failedLinks(gl, () => visualizer.loadPreset(lighter, 0)).length === 0) {
      return `MilkDrop: "${name}" asks for what this renderer lacks (${failed[0] ?? ''}), so its ${stages.join(' and ')} shader runs as the default`;
    }
  }
  return `MilkDrop: "${name}" has shaders this renderer cannot run (${failed[0] ?? ''})`;
}

export function presetLoaded(name: string): boolean {
  return butterchurn !== undefined && scope.__pfMilkdrop?.[name] !== undefined;
}

export class MilkdropRenderer implements MilkdropHost {
  private readonly running = new Map<object, Running>();

  hasPreset(name: string): boolean {
    return presetLoaded(name);
  }

  /** Runs `body` with `Math.random` drawing from this layer's generator (mulberry32). */
  private seeded<T>(state: Running, body: () => T): T {
    const original = Math.random;
    Math.random = () => {
      state.random = (state.random + 0x6d2b79f5) | 0;
      let t = Math.imul(state.random ^ (state.random >>> 15), 1 | state.random);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    try {
      return body();
    } finally {
      Math.random = original;
    }
  }

  private start(request: MilkdropRequest): Running {
    this.release(request.owner);
    const canvas = document.createElement('canvas');
    canvas.width = request.width;
    canvas.height = request.height;
    // Never played: it only tells Butterchurn the sample rate of what it is handed.
    const audio = new OfflineAudioContext(2, 1024, WAVEFORM_RATE);
    const state = {
      canvas,
      key: this.keyOf(request),
      random: request.seed | 0,
      frame: -1,
      problem: null,
    } as Running;
    const visualizer = this.seeded(state, () => {
      if (butterchurn === undefined) throw new Error('Butterchurn is not loaded');
      const created = butterchurn.createVisualizer(audio, canvas, { width: request.width, height: request.height, pixelRatio: 1, textureRatio: 1 });
      state.problem = loadChecked(created, canvas, request.preset);
      return created;
    });
    const running: Running = { ...state, visualizer };
    this.running.set(request.owner, running);
    return running;
  }

  private keyOf(request: MilkdropRequest): string {
    return `${request.preset}|${request.seed}|${request.width}×${request.height}`;
  }

  private step(state: Running, request: MilkdropRequest, frame: number): void {
    const bytes = request.samples(frame);
    this.seeded(state, () => state.visualizer.render({
      audioLevels: { timeByteArray: bytes, timeByteArrayL: bytes, timeByteArrayR: bytes },
      elapsedTime: request.frameSeconds,
    }));
    state.frame = frame;
  }

  frame(request: MilkdropRequest): TexImageSource {
    let state = this.running.get(request.owner);
    // A driver reset takes this context too, and Butterchurn would go on drawing into nothing.
    const lost = state?.canvas.getContext('webgl2')?.isContextLost() === true;
    if (state === undefined || state.key !== this.keyOf(request) || lost) state = this.start(request);
    const target = request.frameIndex;
    if (state.frame === target) return state.canvas;

    const behind = target < state.frame;
    if (request.exact) {
      // What came before is part of the picture, so only the whole way there will do.
      if (behind) state = this.start(request);
      for (let frame = state.frame + 1; frame <= target; frame += 1) this.step(state, request, frame);
      return state.canvas;
    }
    if (behind || target - state.frame > CATCH_UP_FRAMES) {
      state = this.start(request);
      state.frame = Math.max(-1, target - SETTLE_FRAMES);
    }
    for (let frame = state.frame + 1; frame <= target; frame += 1) this.step(state, request, frame);
    return state.canvas;
  }

  problem(owner: object): string | null {
    return this.running.get(owner)?.problem ?? null;
  }

  release(owner: object): void {
    const state = this.running.get(owner);
    if (state === undefined) return;
    this.running.delete(owner);
    state.canvas.getContext('webgl2')?.getExtension('WEBGL_lose_context')?.loseContext();
  }
}

/** The picture of a preset on a test signal, for the browser's cards. */
export function presetStill(host: MilkdropRenderer, preset: string, width: number, height: number, frames: number): HTMLCanvasElement | null {
  if (!host.hasPreset(preset)) return null;
  const owner = {};
  const bytes = new Uint8Array(1024);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const source = host.frame({
    owner, preset, width, height, seed: 1, frameIndex: frames - 1, frameSeconds: 1 / 30, exact: true,
    samples: (frame) => {
      // A kick and a tone on a beat, loud enough to wake a preset that only moves with the music.
      const loud = frame % 15 < 4 ? 1 : 0.25;
      for (let i = 0; i < bytes.length; i += 1) bytes[i] = 128 + Math.round(110 * loud * Math.sin(i * (0.02 + (frame % 45) * 0.002)));
      return bytes;
    },
  });
  canvas.getContext('2d')?.drawImage(source as CanvasImageSource, 0, 0);
  host.release(owner);
  return canvas;
}
